typedef long long ll;

int solve(vector<int>& a, int k) {
    int l = 0, r = (int)a.size() - 1;
    while (l < r) {
        int s = a[l] + a[r];
        if (s == k) return 1;
        if (s < k) l++; else r--;
    }
    return 0;
}

