    while (t--) {
        int n, k;
        cin >> n >> k;
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];
        sort(a.begin(), a.end());
        cout << (solve(a, k) ? "YES" : "NO") << "\n";
    }
    return 0;
}

